mapper.update:
UPDATE delivery
SET d_stats = #{d_stats}
WHERE d_no = #{d_no}

mapper.select:
SELECT d.d_no, d.d_addr, d.d_lat, d.d_lng, d.d_cooking_time, d.d_delivery_time, d.d_arrival_time, d.d_stats, d.d_reg_date, d.r_no, d.u_no, r.r_name, NVL((SELECT SUM(dvm_price * dvm_count) FROM dv_menu WHERE d_no = d.d_no), 0) AS d_total_price FROM delivery d JOIN restaurant r ON d.r_no = r.r_no WHERE d.r_no = #{r_no}
AND d.d_stats = #{d_stats}
AND d.d_reg_date >= TO_DATE(#{startDate}, 'YYYY-MM-DD')
AND d.d_reg_date < TO_DATE(#{endDate}, 'YYYY-MM-DD') + 1
ORDER BY d.d_reg_date DESC
